<script setup>
import { ref, computed, onMounted } from 'vue';
import { ElMessage, ElMessageBox } from 'element-plus';
import { api } from '../api/index.js';
const feeds = ref([]), rules = ref({}), selected = ref(''), loading = ref(false), error = ref(''), feedDialog = ref(false), ruleDialog = ref(false), saving = ref(false), editing = ref(false), feedForm = ref({ url: '', path: '' }), ruleName = ref(''), ruleForm = ref({});
function flatten(tree, prefix = '') { const result = []; for (const [name, node] of Object.entries(tree ?? {})) { if (!node || typeof node !== 'object') continue; const full = prefix ? `${prefix}\\${name}` : name; if (node.url) result.push({ ...node, name, path: full }); else result.push(...flatten(node, full)); } return result; }
const currentFeed = computed(() => feeds.value.find(f => f.path === selected.value));
const ruleRows = computed(() => Object.entries(rules.value).map(([name, rule]) => ({ name, ...rule })));
async function load() { loading.value = true; try { const [rss, r] = await Promise.all([api('/qbittorrent/rss', { quiet: true }), api('/qbittorrent/rss/rules', { quiet: true })]); feeds.value = flatten(rss); rules.value = r; if (!feeds.value.some(f => f.path === selected.value)) selected.value = feeds.value[0]?.path ?? ''; error.value = ''; } catch (e) { error.value = e.message; } finally { loading.value = false; } }
onMounted(load);
async function addFeed() { saving.value = true; try { await api('/qbittorrent/rss/feeds', { method: 'POST', body: feedForm.value }); feedDialog.value = false; feedForm.value = { url: '', path: '' }; ElMessage.success('订阅已添加'); await load(); } catch {} finally { saving.value = false; } }
async function removeFeed(feed) { try { await ElMessageBox.confirm(`删除订阅“${feed.name}”？已下载的文件会保留。`, '删除订阅', { type: 'warning', confirmButtonText: '删除', cancelButtonText: '取消' }); await api('/qbittorrent/rss/feeds', { method: 'DELETE', body: { path: feed.path } }); await load(); } catch {} }
async function refresh() { try { await api('/qbittorrent/rss/refresh', { method: 'POST', body: { path: selected.value } }); ElMessage.success('已请求刷新订阅'); await load(); } catch {} }
function editRule(row) { editing.value = Boolean(row); ruleName.value = row?.name ?? ''; ruleForm.value = { enabled: true, useRegex: false, mustContain: '', mustNotContain: '', episodeFilter: '', smartFilter: false, affectedFeeds: [], ignoreDays: 0, addPaused: null, assignedCategory: '', savePath: '', ...(row ?? {}) }; delete ruleForm.value.name; ruleDialog.value = true; }
async function saveRule() { saving.value = true; try { await api(`/qbittorrent/rss/rules/${encodeURIComponent(ruleName.value)}`, { method: 'PUT', body: ruleForm.value }); ruleDialog.value = false; ElMessage.success('下载规则已保存'); await load(); } catch {} finally { saving.value = false; } }
async function removeRule(name) { try { await ElMessageBox.confirm(`删除下载规则“${name}”？`, '删除规则', { type: 'warning', confirmButtonText: '删除', cancelButtonText: '取消' }); await api(`/qbittorrent/rss/rules/${encodeURIComponent(name)}`, { method: 'DELETE' }); await load(); } catch {} }
const external = value => { try { const u = new URL(value); return ['http:', 'https:'].includes(u.protocol) ? u.href : undefined; } catch { return undefined; } };
</script>
<template><el-alert v-if="error" :title="error" type="error" show-icon :closable="false" class="notice" /><div class="rss-layout" v-loading="loading"><section class="panel"><div class="panel-header"><h2>订阅源 <span class="muted">{{ feeds.length }}</span></h2><el-button size="small" type="primary" plain @click="feedDialog = true">添加</el-button></div><button v-for="feed in feeds" :key="feed.path" class="feed" :class="{ active: selected === feed.path }" @click="selected = feed.path">{{ feed.path }}<span>{{ feed.url }}</span></button><div v-if="!feeds.length" class="empty-hint">添加你的第一个 RSS 订阅源。</div><div class="feed-actions"><el-button size="small" @click="load">重新读取</el-button><el-button v-if="currentFeed" size="small" type="danger" text @click="removeFeed(currentFeed)">删除选中</el-button></div></section><section class="panel"><div class="panel-header"><h2>{{ currentFeed?.name || '订阅文章' }}</h2><el-button size="small" :disabled="!selected" @click="refresh">刷新订阅</el-button></div><div class="table-wrap"><el-table :data="currentFeed?.articles || []" max-height="380"><el-table-column label="文章" min-width="260"><template #default="{ row }"><a v-if="external(row.link)" :href="external(row.link)" target="_blank" rel="noopener noreferrer" class="article-title">{{ row.title }}</a><span v-else>{{ row.title }}</span></template></el-table-column><el-table-column label="发布时间" width="170"><template #default="{ row }">{{ row.date ? new Date(row.date).toLocaleString('zh-CN') : '—' }}</template></el-table-column><template #empty><div class="empty-hint">该订阅尚无文章，可尝试刷新。</div></template></el-table></div></section></div><section class="panel"><div class="panel-header"><div><h2>自动下载规则</h2><p class="muted">RSS 保存目录需位于 Jellyfin 媒体库挂载目录内。</p></div><el-button type="primary" @click="editRule()">新建规则</el-button></div><div class="table-wrap"><el-table :data="ruleRows"><el-table-column prop="name" label="规则名称" min-width="140" /><el-table-column label="状态" width="100"><template #default="{ row }"><el-tag :type="row.enabled ? 'success' : 'info'" round>{{ row.enabled ? '启用' : '停用' }}</el-tag></template></el-table-column><el-table-column prop="mustContain" label="包含条件" min-width="140" show-overflow-tooltip /><el-table-column label="匹配模式" width="110"><template #default="{ row }">{{ row.useRegex ? '正则表达式' : '关键词' }}</template></el-table-column><el-table-column prop="savePath" label="保存目录" min-width="200" show-overflow-tooltip /><el-table-column label="操作" width="145"><template #default="{ row }"><el-button text type="primary" @click="editRule(row)">编辑</el-button><el-button text type="danger" @click="removeRule(row.name)">删除</el-button></template></el-table-column></el-table></div></section><el-dialog v-model="feedDialog" title="添加 RSS 订阅" width="min(520px, 94vw)"><el-form label-position="top" @submit.prevent="addFeed"><el-form-item label="订阅 URL"><el-input v-model="feedForm.url" placeholder="https://example.com/rss" /></el-form-item><el-form-item label="名称 / 路径（可选）"><el-input v-model="feedForm.path" placeholder="例如：电视剧\\我的订阅" /></el-form-item></el-form><template #footer><el-button @click="feedDialog = false">取消</el-button><el-button type="primary" :loading="saving" :disabled="!feedForm.url" @click="addFeed">添加订阅</el-button></template></el-dialog><el-dialog v-model="ruleDialog" :title="editing ? '编辑下载规则' : '新建下载规则'" width="min(650px, 94vw)"><el-form label-position="top"><el-form-item label="规则名称"><el-input v-model="ruleName" :disabled="editing" /></el-form-item><div class="toolbar" style="margin-bottom:18px"><el-switch v-model="ruleForm.enabled" active-text="启用规则" /><el-switch v-model="ruleForm.useRegex" active-text="正则匹配" /><el-switch v-model="ruleForm.smartFilter" active-text="智能剧集筛选" /></div><el-form-item label="包含条件"><el-input v-model="ruleForm.mustContain" placeholder="关键词或正则表达式" /></el-form-item><el-form-item label="排除条件"><el-input v-model="ruleForm.mustNotContain" /></el-form-item><el-form-item label="剧集筛选"><el-input v-model="ruleForm.episodeFilter" placeholder="例如：1x1-13;" /></el-form-item><el-form-item label="应用到订阅"><el-select v-model="ruleForm.affectedFeeds" multiple allow-create filterable style="width:100%"><el-option v-for="feed in feeds" :key="feed.url" :label="feed.path" :value="feed.url" /></el-select></el-form-item><el-form-item label="保存目录（qBittorrent 服务器路径）"><el-input v-model="ruleForm.savePath" placeholder="/MediasVol3/series 或 /MediasVol3/movies" /></el-form-item><el-form-item label="下载分类"><el-input v-model="ruleForm.assignedCategory" placeholder="可选，例如 series / movies" /></el-form-item><div class="toolbar"><span class="muted">重复下载间隔（天）</span><el-input-number v-model="ruleForm.ignoreDays" :min="0" :max="36500" /><span class="muted">添加后状态</span><el-select v-model="ruleForm.addPaused" style="width:140px"><el-option label="使用默认设置" :value="null" /><el-option label="开始下载" :value="false" /><el-option label="暂停下载" :value="true" /></el-select></div></el-form><template #footer><el-button @click="ruleDialog = false">取消</el-button><el-button type="primary" :loading="saving" :disabled="!ruleName" @click="saveRule">保存规则</el-button></template></el-dialog></template>
